/* Coordinates are shared by the phone preview and its downloaded image. */
const RECORD_LAYOUT={width:600,height:1066,stats:{x:55,y:140,width:260,height:270},names:{x:55,y:480,width:220,height:200},route:{x:295,y:445,width:260,height:565},photoRadius:23};
function createRecordProjection(points){let minX=Infinity,maxX=-Infinity,minZ=Infinity,maxZ=-Infinity;for(const p of points){minX=Math.min(minX,p.x);maxX=Math.max(maxX,p.x);minZ=Math.min(minZ,p.z);maxZ=Math.max(maxZ,p.z)}if(!points.length)minX=maxX=minZ=maxZ=0;const area=RECORD_LAYOUT.route,pad=RECORD_LAYOUT.photoRadius+8;const scale=Math.min((area.width-2*pad)/Math.max(120,maxX-minX),(area.height-2*pad)/Math.max(160,maxZ-minZ));const cx=(minX+maxX)/2,cz=(minZ+maxZ)/2;return p=>({x:area.x+area.width/2+(p.x-cx)*scale,y:area.y+area.height/2-(p.z-cz)*scale})}
